import type { Href } from 'one'

// routes.d.ts is generated by one in dev, so new paths are cast until it catches up
const href = (path: string) => path as Href

export const ENGINE_ROUTES = {
  index: href('/engine'),
  workspace: (workspaceId: string) => href(`/engine/${workspaceId}`),
  brand: (workspaceId: string) => href(`/engine/${workspaceId}/brand`),
  integrations: (workspaceId: string) => href(`/engine/${workspaceId}/integrations`),
  audit: (workspaceId: string) => href(`/engine/${workspaceId}/audit`),
  audiences: (workspaceId: string) => href(`/engine/${workspaceId}/audiences`),
  experiments: (workspaceId: string) => href(`/engine/${workspaceId}/experiments`),
  experiment: (workspaceId: string, experimentId: string) =>
    href(`/engine/${workspaceId}/experiments/${experimentId}`),
  measurement: (workspaceId: string) => href(`/engine/${workspaceId}/measurement`),
  settings: (workspaceId: string) => href(`/engine/${workspaceId}/settings`),
} as const

export type EngineSection =
  | 'command-centre'
  | 'audiences'
  | 'experiments'
  | 'measurement'
  | 'brand'
  | 'integrations'
  | 'audit'
  | 'settings'

export function getEngineSection(pathname: string): EngineSection {
  const segments = pathname.split('/').filter(Boolean)
  const last = segments[2]
  switch (last) {
    case 'audiences':
      return 'audiences'
    case 'experiments':
      return 'experiments'
    case 'measurement':
      return 'measurement'
    case 'brand':
      return 'brand'
    case 'integrations':
      return 'integrations'
    case 'audit':
      return 'audit'
    case 'settings':
      return 'settings'
    default:
      return 'command-centre'
  }
}
